import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { CahierPedagogiqueService } from '../../core/services/cahier-pedagogique.service';
import { ProfService } from '../../core/services/prof.service';

@Component({
  selector: 'app-prof-public',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './prof-public.component.html',
  styleUrls: ['./prof-public.component.scss']
})
export class ProfPublicComponent implements OnInit {
  classes: any[] = [];
  cahiers: any[] = [];
  selectedClassId: number | null = null;
  selectedFile: File | null = null;
  fileName = '';
  uploading = false;

  constructor(
    private cahierService: CahierPedagogiqueService,
    private profService: ProfService,
    private router: Router
  ) {}

  ngOnInit() {
    this.loadClasses();
  }

  gotoClasses() {
    this.router.navigate(['/dashboard']);
  }

  /** 🔹 Charger les classes du professeur connecté */
  loadClasses() {
    this.profService.getMyClasses().subscribe({
      next: data => (this.classes = data || []),
      error: err => console.error('Erreur chargement classes:', err)
    });
  }

  /** 🔹 Charger les cahiers d’une classe */
  loadCahiers() {
    if (!this.selectedClassId) return;

    this.cahierService.getCahiersByClass(this.selectedClassId).subscribe({
      next: res => {
        this.cahiers = (res || []).sort(
          (a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        );
      },
      error: err => console.error('Erreur chargement cahiers:', err)
    });
  }

  /** 🔹 Sélection du fichier */
  onFileSelected(event: any) {
    this.selectedFile = event.target.files[0];
  }

  /** 🔹 Upload du cahier */
  uploadCahier() {
    if (!this.selectedFile || !this.selectedClassId) {
      alert('Veuillez choisir une classe et un fichier.');
      return;
    }

    this.uploading = true;
    this.cahierService.uploadCahier(this.selectedFile, this.selectedClassId, this.fileName).subscribe({
      next: () => {
        this.uploading = false;
        this.fileName = '';
        this.selectedFile = null;
        this.loadCahiers();
      },
      error: err => {
        console.error('Erreur upload:', err);
        this.uploading = false;
      }
    });
  }

  /** 🔹 Suppression d’un cahier */
  deleteCahier(id: number) {
    if (!confirm('Voulez-vous vraiment supprimer ce cahier ?')) return;

    this.cahierService.deleteCahier(id).subscribe({
      next: () => {
        this.cahiers = this.cahiers.filter(c => c.id !== id);
        alert('🗑️ Cahier supprimé avec succès');
      },
      error: err => console.error('Erreur suppression:', err)
    });
  }
}
<div class="public-container container py-5">
  <!-- 🧭 En-tête -->
  <div
    class="dashboard-header d-flex flex-wrap justify-content-between align-items-center mb-4 p-3 rounded shadow-sm bg-light border">
    <div class="mb-3 mb-md-0">
      <h1 class="dashboard-title fw-bold text-primary mb-1">
        <i class="bi bi-journal-text me-2"></i> Cahier pédagogique
      </h1>
      <p class="dashboard-subtitle text-muted mb-0">
        📖 Espace personnel du professeur – planifiez vos séances et suivez vos activités
      </p>
    </div>

    <div class="d-flex flex-wrap gap-2">
      <button class="btn btn-outline-primary d-flex align-items-center px-3" (click)="gotoClasses()">
        <i class="bi bi-people-fill me-2"></i>
        <span>Tableau de bord</span>
      </button>
    </div>
  </div>

  <!-- 🏫 Sélection de classe + upload -->
  <div class="card shadow-sm mb-4 p-4">
    <h5 class="fw-bold mb-3">🧩 Choisir une classe</h5>

    <div class="row g-3 align-items-end">
      <div class="col-md-5">
        <label class="form-label">Classe</label>
        <select class="form-select" [(ngModel)]="selectedClassId" (change)="loadCahiers()">
          <option [ngValue]="null">-- Sélectionner une classe --</option>
          <option *ngFor="let c of classes" [value]="c.id">{{ c.name }}</option>
        </select>
      </div>

      <div class="col-md-4">
        <label class="form-label">Nom du fichier / titre</label>
        <input
          type="text"
          class="form-control"
          [(ngModel)]="fileName"
          placeholder="Ex: Séance 3 - Réseau LAN" />
      </div>

      <div class="col-md-3">
        <label class="form-label">Fichier</label>
        <input type="file" class="form-control" (change)="onFileSelected($event)" />
      </div>

      <div class="col-12 text-end mt-3">
        <button
          class="btn btn-primary"
          (click)="uploadCahier()"
          [disabled]="!selectedClassId || !selectedFile || uploading">
          <ng-container *ngIf="!uploading">
            <i class="bi bi-cloud-upload me-2"></i> Uploader
          </ng-container>
          <ng-container *ngIf="uploading">
            <span class="spinner-border spinner-border-sm me-2"></span> Envoi en cours...
          </ng-container>
        </button>
      </div>
    </div>
  </div>

  <!-- 📚 Liste des cahiers -->
  <div *ngIf="cahiers.length > 0; else noCahiers" class="row g-4">
    <div class="col-md-6 col-lg-4" *ngFor="let cahier of cahiers">
      <div class="card shadow-sm h-100">
        <div class="card-body">
          <h5 class="card-title">{{ cahier.fileName }}</h5>
          <p class="card-text text-muted small mb-2">
            <i class="bi bi-calendar-event me-1"></i>
            {{ cahier.createdAt | date: 'dd MMM yyyy, HH:mm' }}
          </p>
          <div class="d-flex">
            <a
              [href]="cahier.fileUrl"
              download
              class="btn btn-outline-primary btn-sm w-50">
              <i class="bi bi-download me-1"></i> Télécharger
            </a>
            <button
              class="btn btn-outline-danger btn-sm w-50 ms-2"
              (click)="deleteCahier(cahier.id)">
              <i class="bi bi-trash"></i>
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- 📨 Aucun cahier -->
  <ng-template #noCahiers>
    <div class="alert alert-info text-center mt-4">
      📭 Aucun cahier pédagogique n’a encore été uploadé pour cette classe.
    </div>
  </ng-template>
</div>
